<?php $this->layout('default'); use Moves\Services\CmsQuery as Q; use Moves\Services\PlatformBilling as B; use Moves\Support\CmsView as V;
$filters = ['q' => V::queryString('q'), 'status' => V::queryString('status')]; $result = B::charges($filters, V::queryPage());
$count = static fn (string $s): string => (string) Q::value('SELECT COUNT(*) FROM platform_charges WHERE status=?', [$s]); ?>
<?= V::kpis([['clock', 'Pendentes', $count('pending'), 'dentro do prazo'], ['alert', 'Vencidas', $count('overdue'), 'fora do prazo'], ['check', 'Pagas', $count('paid'), 'com comprovante'], ['card', 'Falhas', $count('failed'), 'tentativas sem sucesso']]) ?>
<div class="cms-alert cms-alert-info">Nenhum provedor de pagamento está integrado. Esta área não executa cobranças reais. Contas a Receber dos clientes ficam no App.</div>
<section class="cms-list"><?= V::listHead('Lista de cobranças', $result['total'] . ' registro(s)', V::searchForm('Buscar referência ou assinante', ['status' => [$filters['status'], ['' => 'Todas'] + V::CHARGE_STATUS, 'Situação']])) ?>
<?php if ($result['rows'] === []): ?><?= V::empty('Nenhuma cobrança encontrada.') ?><?php else: ?><div class="cms-table-wrap" tabindex="0" role="region" aria-label="Cobranças"><table><thead><tr><th>Referência</th><th>Assinante</th><th>Plano</th><th>Vencimento</th><th class="num">Valor</th><th>Status</th><th class="cms-th-actions">Ações</th></tr></thead><tbody><?php foreach ($result['rows'] as $c): ?><tr><td><code class="cms-chip"><?= V::e($c['reference']) ?></code></td><td><?= V::e($c['owner_name']) ?></td><td><?= V::e($c['plan_name']) ?></td><td><?= V::date($c['due_date'], false) ?></td><td class="num"><?= V::money($c['amount']) ?></td><td><?= V::badge($c['status'], V::CHARGE_STATUS[$c['status']] ?? $c['status']) ?></td><td class="cms-td-actions"><?= V::iconLink('/cobrancas/' . (int) $c['id'], 'Abrir', 'eye') ?></td></tr><?php endforeach; ?></tbody></table></div><?= V::pager($result) ?><?php endif; ?></section>
